export const TELEPORT_SPEED = 12;
export const keyJump = (tr: TruthTrack, a: number, b: number): boolean => {
  const d = Math.hypot(kX(tr, b) - kX(tr, a), kY(tr, b) - kY(tr, a));
  if (d <= TELEPORT_TILES) return false;
  const st = kS(tr, a);
  /* 건물(BW 종류 106~ · 떠서 나는 테란 건물)은 '서 있음' 갈래로 안 가른다 — 뜬 채 나는 키가 그 갈래로 올 수 있다. 속도 자만 본다. */
  if ((tr.types[a] ?? 0) < 106 && (st === TRUTH_ST_IDLE || st === TRUTH_ST_INSIDE || st === TRUTH_ST_BURROW)) return true;
  return d / Math.max(0.001, tr.kt[b] - tr.kt[a]) > TELEPORT_SPEED;
};

/** t초일 때 이 개체의 자리·방향·상태. 아직 안 태어났으면 null. */
export function posAtTruth(
  tr: TruthTrack, t: number,
  cur?: { i: number },
): { x: number; y: number; hdg: number; state: number } | null {
  const n = tr.kt.length;
  if (n === 0) return null;
  const kt = tr.kt;
  if (t < kt[0]) return null;
  let lo = -1;
  if (cur) {
    const h9 = cur.i;
    if (h9 >= 0 && (h9 === n - 1 ? kt[h9] <= t : kt[h9] <= t && kt[h9 + 1] > t)) lo = h9;
    else if (h9 >= -1 && h9 + 1 < n && kt[h9 + 1] <= t && (h9 + 2 >= n || kt[h9 + 2] > t)) lo = h9 + 1;
  }
  if (lo < 0) {
    lo = 0;
    let hi = n - 1;
    while (lo < hi) {
      const mid = (lo + hi + 1) >> 1;
      if (kt[mid] <= t) lo = mid; else hi = mid - 1;
    }
  }
  if (cur) cur.i = lo;
  const st = kS(tr, lo);
  /* 죽는 순간의 키(GONE)는 덤퍼가 개체를 걷어 내며 적는 것이라 자리가 마지막으로 산 자리와 다를 때가 있다 —
     그 키 쪽으로 메우지도, 그 위에 서지도 않고 마지막으로 산 키에 못 박는다(지적: 오버로드가 되돌아와 터짐). */
  if (st === TRUTH_ST_GONE && lo > 0) {
    return { x: kX(tr, lo - 1), y: kY(tr, lo - 1), hdg: kH(tr, lo - 1), state: st };
  }
  if (lo === n - 1) return { x: kX(tr, lo), y: kY(tr, lo), hdg: kH(tr, lo), state: st };
  const j = lo + 1;
  if (kS(tr, j) === TRUTH_ST_GONE) return { x: kX(tr, lo), y: kY(tr, lo), hdg: kH(tr, lo), state: st };
  if (keyJump(tr, lo, j)) return { x: kX(tr, lo), y: kY(tr, lo), hdg: kH(tr, lo), state: st };   // 순간이동(위 keyJump ★) — 뒤 키 때 짠
  const span = kt[j] - kt[lo];
  const u = span > 0 ? Math.min(1, Math.max(0, (t - kt[lo]) / span)) : 0;
  /* 각은 선형으로 안 메운다 — 앞 키의 각에서 초당 TURN_DPS도로 따라가다 목표에 닿으면 멈춘다(원작의 회전).
     키에 늦지 않게 필요한 속도(need)와 견줘 더 빠른 쪽을 쓰므로 다음 키에 닿는 순간의 각은 그 키의 각 그대로다. */
  const h0 = kH(tr, lo);
  const dh = angDiff(h0, kH(tr, j));
  const dt = t - kt[lo];
  const need = span > 0 ? Math.abs(dh) / span : 0;
  const turned = Math.min(Math.abs(dh), Math.max(TURN_DPS, need) * dt);
  const x0 = kX(tr, lo); const y0 = kY(tr, lo);
  return {
    x: x0 + (kX(tr, j) - x0) * u,
    y: y0 + (kY(tr, j) - y0) * u,
    hdg: norm360(h0 + Math.sign(dh) * turned),
    state: st,
  };
}

/** base64 → 바이트. atob는 라틴1 문자열을 주므로 코드포인트를 그대로 옮긴다. */
function fromBase64(s: string): Uint8Array {
  const bin = atob(s);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i += 1) out[i] = bin.charCodeAt(i);
  return out;
}

/** zlib 풀기 — 브라우저가 해 준다(DecompressionStream). 없는 환경이면 던진다. */
async function inflate(bytes: Uint8Array): Promise<Uint8Array> {
  const DS = (globalThis as { DecompressionStream?: typeof DecompressionStream }).DecompressionStream;
  if (!DS) throw new Error("이 브라우저는 DecompressionStream이 없다");
  const stream = new Blob([bytes as BlobPart]).stream().pipeThrough(new DS("deflate"));
  return new Uint8Array(await new Response(stream).arrayBuffer());
}

/** 바이트열을 앞에서부터 훑는 작은 커서 — 꼴이 한 줄로 이어져 있어 되감을 일이 없다. */
class Cursor {
  private p = 0;
  private readonly b: Uint8Array;
  /* 매개변수 속성(constructor(private b))은 안 쓴다 — 이 리포는 erasableSyntaxOnly라
     타입만 지워서는 자바스크립트가 안 되는 문법을 금한다. */
  constructor(b: Uint8Array) { this.b = b; }
  u8(): number { return this.b[this.p++]; }
  u16(): number { const v = this.b[this.p] | (this.b[this.p + 1] << 8); this.p += 2; return v; }
  u32(): number {
    const v = (this.b[this.p] | (this.b[this.p + 1] << 8) | (this.b[this.p + 2] << 16)
      | (this.b[this.p + 3] << 24)) >>> 0;
    this.p += 4;
    return v;
  }
  i32(): number { return this.u32() | 0; }
  f32(): number {
    const v = new DataView(this.b.buffer, this.b.byteOffset + this.p, 4).getFloat32(0, true);
    this.p += 4;
    return v;
  }
  /** UTF-8 글 n바이트. 사람 이름이 여기로 온다(한글은 덤퍼가 CP949에서 옮겨 놓는다). */
  utf8(n: number): string {
    const s = new TextDecoder().decode(this.b.subarray(this.p, this.p + n));
    this.p += n;
    return s;
  }

  /** 7비트씩 담긴 수 + zigzag 되돌리기 — 음수도 작은 바이트로 들어온다. */
  varint(): number {
    let z = 0;
    let shift = 0;
    for (;;) {
      const c = this.b[this.p++];
      z |= (c & 0x7f) << shift;
      if (!(c & 0x80)) break;
      shift += 7;
    }
    z >>>= 0;
    return (z >>> 1) ^ -(z & 1);
  }
  get left(): number { return this.b.length - this.p; }
  /** n 바이트를 떼어 낸다(복사 — 큰 풀린 판을 붙잡지 않게). */
  take(n: number): Uint8Array { const v = this.b.slice(this.p, this.p + n); this.p += n; return v; }
}
/** 곁 꾸러미 절 하나 — 줄 수 · 몸 바이트(해독은 쓸 때 아래 raw17* 로). */
export type Raw17Sec = { n: number; b: Uint8Array };
/** 곁 꾸러미 정밀 자리 줄 [초, 태그, x 픽셀, y 픽셀, 방향(0~255), 속력(fp8 raw), 이동 방향(0~255)] — 표본 간격마다 바뀐 몸만. */
export function raw17Pos(sec: Raw17Sec, fps: number): [number, number, number, number, number, number, number][] {
  const c = new Cursor(sec.b); const out: [number, number, number, number, number, number, number][] = []; let pf = 0;
  for (let i = 0; i < sec.n; i += 1) { pf += c.varint(); out.push([pf / fps, c.u32(), c.u16(), c.u16(), c.u8(), c.varint(), c.u8()]); }
  return out;
}
/** 곁 꾸러미 탄 줄 — 생김 {초, 번호, 무기, 임자, 쏜 태그, 표적 태그, x, y, 표적 x, 표적 y} · 사라짐 {초, 번호, gone}. */
export function raw17Bullets(sec: Raw17Sec, fps: number): ({ t: number; id: number; gone: true } | { t: number; id: number; wpn: number; owner: number; src: number; tgt: number; x: number; y: number; tx: number; ty: number })[] {
  const c = new Cursor(sec.b); const out: ReturnType<typeof raw17Bullets> = []; let pf = 0;
  for (let i = 0; i < sec.n; i += 1) {
    const k = c.u8(); pf += c.varint(); const id = c.u32();
    if (k === 1) { out.push({ t: pf / fps, id, gone: true }); continue; }
    if (k === 2) continue;   // 닿음(판 17 탄 절과 같은 꼴 · 2026-11-04) — 여기선 안 쓴다
    out.push({ t: pf / fps, id, wpn: c.u16(), owner: c.u8(), src: c.u32(), tgt: c.u32(), x: c.u16(), y: c.u16(), tx: c.u16(), ty: c.u16() });
  }
  return out;
}
/** 곁 꾸러미 사람 줄 [초, 사람, 갈래, 값] — 갈래표는 덤퍼 bwdump.cpp 판 17 '사람' 주석(0~2 보급 쓴 몫 · 3~5 상한 · 6·7 점수 · 8 동맹 · 9 시야 공유 · … · 1000+종류 수 · 2000+완성 수). */
export function raw17Players(sec: Raw17Sec, fps: number): [number, number, number, number][] {
  const c = new Cursor(sec.b); const out: [number, number, number, number][] = []; let pf = 0;
  for (let i = 0; i < sec.n; i += 1) { pf += c.varint(); out.push([pf / fps, c.u8(), c.u16(), c.u32()]); }
  return out;
}
/** 곁 꾸러미 타일 줄 [초, 타일 번호(y × 폭 + x), 깃발(크립 0x40 · 크립 물러남 0x1000 · 차지됨 0x800 …), 보임 비트, 밝힘 비트] — 24 프레임마다 바뀐 칸. */
export function raw17Tiles(sec: Raw17Sec & { w: number; h: number }, fps: number): [number, number, number, number, number][] {
  const c = new Cursor(sec.b); const out: [number, number, number, number, number][] = []; let pf = 0;
  for (let i = 0; i < sec.n; i += 1) { pf += c.varint(); const ti = c.u32(); const v = c.u32(); out.push([pf / fps, ti, v >>> 16, (v >>> 8) & 0xff, v & 0xff]); }
  return out;
}

/**
 * 서버가 준 문자열(base64)을 트랙으로 푼다.
 *
 * 던지지 않는다 — 꼴이 낯설거나 못 풀면 null을 준다. 부르는 쪽은 그때 옛 길로 돌아가면 된다.
 */
/** 머리 다섯 바이트만 엿본다 — **못 푼 까닭을 말하기 위한** 자다.
 *
 *  decodeTruthTracks는 꼴이 낯설면 그냥 null을 준다(그게 부르는 쪽에 편하다). 그런데
 *  그러면 화면이 "재생할 수 없는 게임이에요"라고만 하고 **왜인지는 아무 데도 안 남는다**.
 *  판이 범위 밖이라 물리친 것인지, 애초에 OBWT가 아닌 것인지, 자취가 안 온 것인지가
 *  갈리지 않으면 서버를 고쳐야 할 일과 화면을 고쳐야 할 일을 구분할 수가 없다.
 *  전체를 푸는 값(1~2MB)을 치르지 않고 머리만 본다. */
/** 해독기가 읽는 판의 범위 — 화면의 진단 문구는 이 두 값에서 만든다(2026-09, 덤퍼 쪽 답신: 게이트는 8 인데
 *  문구가 "2~7만 읽는다"였다 — 문구와 게이트를 따로 적어 두면 다음 어긋남이 로그에서 안 읽힌다). */
/* ★ 판 11 만 읽는다(2026-09, 요청: "판 10 이하 참값은 재생 안되게") — 하단 인포창·K/D 가 판 11 의 네 절(에너지·탑승·자원량·처치)
   위에 서므로 옛 판은 폴백 없이 물리친다. 덤퍼가 판 11 로 갈리고 일괄 재분석이 돈다. */
export const TRUTH_VER_MIN9 = 11;
/* 판 12 = 판 11 + 선택 줄마다 u8 갈래(아래 SEL_KIND9) — 덤퍼가 갈리고 재분석이 돌기까지 판 11 도 그대로 읽는다(갈래 −1). */
/* 판 13 = 판 12 + 맨 뒤 **데미지 절**(통마다 임자별 준·입은 데미지 · 아래 dmg) — 옛 판은 빈 표다(2026-10). */
/* 판 14 = 판 13 + 맨 뒤 **채집 절**(사람마다 캔 자원 누적 · 아래 gath) — 옛 판은 빈 표다(2026-10-22). */
/* 판 15 = 판 14 + 상태 바이트 0x10 '스팀팩 중'(2026-11-03, 요청: "스팀팩을 데이터에 싣는 방법으로 근본적 해결") — 꼴은 같고 깃발 하나가 는다(옛 판은 0). */
/* 판 16 = 판 15 + 맨 뒤 **상태 절**(마법 타이머·매트릭스·실드·연구 중… 아래 ST16) · **사격 절**(실제 발사 프레임) + 체력 솎기 없음(2026-11-03, 요청: "하나도 빠짐없이 다"). */
/* (판 17 은 만들지 않았다 — 큰 원본은 재생용 참값을 무겁게 하지 않게 **곁 꾸러미 OBWX**(아래 decodeTruthExtra)로 갈랐다 · 2026-11-03.) */
/* 판 17 = 판 16 + 맨 뒤 **탄 절** · **타일 절**(크립·시야 · 12 프레임마다) · 상태 절에 포탑 방향(62) — "탄환·시야·크립·포탑 넷 다 연결하고 참값으로"(2026-11-03). */
export const TRUTH_VER_MAX9 = 17;
/** 선택 갈래(판 12 선택 줄의 낮은 넉 비트) — 높은 넉 비트는 부대 번호(0~9 · 부대 갈래에서만 뜻이 있다). */
export const SEL_KIND9 = {
  /** 마우스로 고름(클릭·끌어 고르기 = Select) — 그 몸들은 그 순간 그 사람 화면 안이었다. */
  click: 0,
  /** 시프트로 더함(ShiftSelect) — 화면 안. */
  add: 1,
  /** 시프트로 뺌(ShiftDeselect) — 화면 안. */
  remove: 2,
  /** 부대 불러오기(숫자키) — 화면을 안 옮긴다. 선택이 그대로여도 한 줄 적는다(두 번 누름을 알아야 한다). */
  recall: 3,
  /** 부대 지정(Ctrl+숫자) — 선택이 안 바뀐다. */
  assign: 4,
  /** 부대에 더함(Shift+숫자) — 선택이 안 바뀐다. */
  groupAdd: 5,
} as const;

export async function peekTruthHead(
  b64: string,
): Promise<{ ok: boolean; version: number } | null> {
  try {
    const raw = await inflate(fromBase64(b64));
    if (raw.length < 5) return null;
    const ok = raw[0] === 0x4f && raw[1] === 0x42 && raw[2] === 0x57 && raw[3] === 0x54;
    return { ok, version: raw[4] };
  } catch {
    return null;
  }
}

/** ★ 참값 곁 꾸러미 OBWX(2026-11-03, 요청: "절대 하나도 빼놓지 마 · 다 나중에 필요해") — 서버 `GET /game-results/{id}/truth-extras` 의 data(base64).
 *  ("원본을 저장하라는 게 아니라 원본이 더 이상 필요 없게 게임 상태를") — 덤퍼가 재생용 참값(OBWT)과 따로 낸 게임 상태: ① 상태 나머지(갈래 40~89 — 명령·표적·
 *  이동 표적·상태 비트·운반·건설 남은 시간·보임 비트·정확한 체력·에너지·…) ② 정밀 자리 ③ 사람. 리플레이 명령 바이트는 없다(탄·타일은 판 17 OBWT 에).
 *  ①은 OBWT 의 stat 과 같은 꼴(태그마다 평평한 [초, 갈래, 값])로 풀고
 *  나머지는 바이트로 들고 있다가 raw17* 로 푼다(정밀 자리만 수백만 줄일 수 있다). 꼴은 덤퍼 bwdump.cpp 'OBWX' 주석. */
export type TruthExtra = {
  fps: number;
  stat: Map<number, Float64Array>;
  pos: Raw17Sec; players: Raw17Sec;
};
export async function decodeTruthExtra(b64: string): Promise<TruthExtra | null> {
  try {
    const c = new Cursor(await inflate(fromBase64(b64)));
    if (c.u8() !== 0x4f || c.u8() !== 0x42 || c.u8() !== 0x57 || c.u8() !== 0x58) return null; // "OBWX"
    if (c.u8() !== 2) return null;   // 판 2 — 탄·타일은 판 17 OBWT 로 옮겼다
    const fps = c.f32();
    const sec9 = (head9 = 0): Raw17Sec & { w: number; h: number } => {
      const len9 = c.u32(); const n9 = c.u32();
      const w9 = head9 ? c.u16() : 0; const h9 = head9 ? c.u16() : 0;
      return { n: n9, b: c.take(len9 - 4 - head9), w: w9, h: h9 };
    };
    const st9 = sec9();
    const stat = new Map<number, Float64Array>();
    { const sc = new Cursor(st9.b); const acc9 = new Map<number, number[]>(); let pf = 0;
      for (let i = 0; i < st9.n; i += 1) {
        pf += sc.varint(); const tag = sc.u32(); const kind = sc.u8(); const v = sc.u32();
        const a9 = acc9.get(tag); if (a9) a9.push(pf / fps, kind, v); else acc9.set(tag, [pf / fps, kind, v]);
      }
      for (const [tg9, a9] of acc9) stat.set(tg9, Float64Array.from(a9)); }
    const pos = sec9(); const players = sec9();
    return { fps, stat, pos, players };
  } catch {
    return null;
  }
}
export async function decodeTruthTracks(b64: string): Promise<TruthTracks | null> {
  try {
    const raw = await inflate(fromBase64(b64));
    const c = new Cursor(raw);
    if (c.u8() !== 0x4f || c.u8() !== 0x42 || c.u8() !== 0x57 || c.u8() !== 0x54) return null; // "OBWT"
    const version = c.u8();
    /* ★★ **판 11~14 만** 읽는다(2026-09, 요청: "판 10 이하 참값은 재생 안되게" — 덤퍼가 판 11 로 일괄 재분석한다). 10 이하는
       그 자리에서 물리친다 — 판 3~10 의 절(떠 있음·자원 밭·은신·표적·업그레이드 태그·임자바뀜·건설·선택)은 늘 있다
       (옛 판 갈래는 2026-10-26 걷었다, 요청: "예전 버전 받게 한 거 다 삭제"). */
    if (version < TRUTH_VER_MIN9 || version > TRUTH_VER_MAX9) return null;
    /** 선택 줄마다 갈래 바이트(판 12). */
    const hasSelKind = version >= 12;
    /** 데미지 절(판 13) — 네 절 뒤, 맨 뒤다. */
    const hasDmg = version >= 13;
    /** 채집 절(판 14) — 데미지 절 뒤, 맨 뒤다. */
    const hasGath = version >= 14;
    /** 상태·사격 절(판 16) — 채집 절 뒤. */
    const has16 = version >= 16;
    /** 탄·타일 절(판 17) — 사격 절 뒤. */
    const has17 = version >= 17;
    const fps = c.f32();
    const trustFrame = c.i32();
    if (!Number.isFinite(fps) || fps <= 0) return null;

    const players: TruthPlayer[] = [];
    const pn = c.u8();
    for (let i = 0; i < pn; i += 1) {
      const owner = c.u8();
      const pid = c.u8();
      const race = c.u8();
      const force = c.u8();
      const controller = c.u8();
      const rgb = c.u32();
      const name = c.utf8(c.u8());
      /* 진짜 개인색이다. 못 읽었으면 **0xffffffff**(색 아님)로 온다 — 빈 글자로 두면
         부르는 쪽이 팀색으로 떨어진다.
         ★ 이 자리가 비는 일이 **크게 줄었다**(뭉치 꼴은 그대로, 값의 뜻만 넓어졌다) —
           여태 덤퍼는 리마스터의 CCLR 구획에서만 색을 읽어, 그 구획이 없는 1.16 이하는
           여덟 명이 전부 '모름'이었다. 이제 머리말의 색 번호를 표준 팔레트로 풀므로
           (SC:R 인게임·screp이 가는 길과 같다) 옛 판에서도 제 색이 온다. 갈래는 그대로
           둔다 — 덜 걸릴 뿐이지 못 읽는 판이 아주 없어진 것은 아니고, **이미 구워 둔
           뭉치는 다시 굽기 전까지 옛 값 그대로**다.
         ★ 옛 덤퍼는 그 자리에 흰색(0xffffff)을 적었다. 그 판들은 여기서 못 가른다(흰색은
           고를 수 있는 색이라서다) — 대신 재생기가 '로스터 색이 한 가지뿐이면 색이 아니다'
           로 걸러 낸다(ReplayMotionPlayer의 personalUsable). */
      const color = rgb === 0xffffffff
        ? "" : `#${(rgb & 0xffffff).toString(16).padStart(6, "0")}`;
      players.push({ owner, pid, race, force, controller, color, name });
    }

    const n = c.u32();
    if (n > 100000) return null;
    const head: { tag: number; owner: number; type: number;
      count: number; hp: number; ic: number; tgt: number; own: { f: number; owner: number }[] }[] = new Array(n);
    for (let i = 0; i < n; i += 1) {
      head[i] = { tag: c.u32(), owner: c.u8(), type: c.u16(),
        count: c.u32(), hp: c.u32(), ic: c.u32(), tgt: c.u32(), own: [] };
      /* 임자바뀜 목록(판 8) — 줄 끝에 u8 수, 바뀜마다 u32 프레임(LE) · u8 새 임자. 차례로 읽는다. */
      const nOwn9 = c.u8();
      for (let k = 0; k < nOwn9; k += 1) head[i].own.push({ f: c.u32(), owner: c.u8() });
    }

    const tracks: TruthTrack[] = [];
    for (let i = 0; i < n; i += 1) {
      const h = head[i];
      const kt = new Float32Array(h.count);
      const kxy = new Int16Array(h.count * 2);
      const kh = new Uint8Array(h.count);
      const kst = new Uint8Array(h.count);
      const types = new Uint16Array(h.count);
      const done = new Uint8Array(h.count);
      const air = new Uint8Array(h.count);
      const cloak = new Uint8Array(h.count);
      const stim = new Uint8Array(h.count);
      let pf = 0;
      let px = 0;
      let py = 0;
      let pt = 0;
      let born = 0;
      let died: number | null = null;
      for (let k = 0; k < h.count; k += 1) {
        pf += c.varint();
        px += c.varint();
        py += c.varint();
        const headingByte = c.u8();
        const stateByte = c.u8();
        /* 상태는 낮은 네 자리뿐이다 — 나머지는 깃발이다(위 꼴 주석). 0x7f로 걷으면
           '떠 있다'(0x40)가 상태 값에 섞여 나는 유닛의 이동이 0x41이 된다. 판 2에서는
           값이 0~8뿐이라 이 마스크가 예전과 똑같은 답을 낸다. */
        const state = stateByte & 0x0f;
        done[k] = stateByte & 0x80 ? 0 : 1;
        air[k] = stateByte & 0x40 ? 1 : 0;
        // 0x20 = 은신 중 — 남아 있던 깃발 자리를 쓴다.
        cloak[k] = stateByte & 0x20 ? 1 : 0;
        // 0x10 = 스팀팩 중(판 15 · 2026-11-03) — 마지막 빈 깃발 자리.
        stim[k] = stateByte & 0x10 ? 1 : 0;
        pt += c.varint();
        types[k] = pt;
        const t = pf / fps;
        if (k === 0) born = t;
        if (state === TRUTH_ST_GONE) died = t;
        kt[k] = t;
        kxy[k * 2] = px;                    // 픽셀 그대로(읽을 때 /32 → 타일)
        kxy[k * 2 + 1] = py;
        kh[k] = headingByte;
        kst[k] = state;
      }
      tracks.push({
        tag: h.tag,
        owner: h.owner,
        kind: BW_UNIT_NAME[h.type] ?? `?${h.type}`,
        born,
        died,
        own: h.own.map((o) => ({ t: o.f / fps, owner: o.owner })),
        kt, kxy, kh, kst,
        types,
        done,
        air,
        cloak,
        stim,
      });
    }

    /* 체력·인터셉터는 자리 키와 따로 온다(섞으면 한쪽이 바뀔 때마다 다른 쪽 키까지
       끌려 나온다). 트랙 차례가 같으므로 같은 차례로 읽어 붙인다. */
    const readTicks = (want: (h: typeof head[number]) => number,
      put: (tr: TruthTrack, v: Float32Array) => void): void => {
      for (let i = 0; i < n; i += 1) {
        const cnt = want(head[i]);
        if (!cnt) continue;
        const out = new Float32Array(cnt * 2);
        let pf = 0;
        let pv = 0;
        for (let k = 0; k < cnt; k += 1) {
          pf += c.varint();
          pv += c.varint();
          out[k * 2] = pf / fps;
          out[k * 2 + 1] = pv;
        }
        put(tracks[i], out);
      }
    };
    readTicks((h) => h.hp, (tr, v) => { tr.hp = v; });
    readTicks((h) => h.ic, (tr, v) => { tr.ic = v; });
    /* 표적 흐름(판 6) — 값이 **태그**라 차이로 안 적혀 있다(순서 없는 이름표라 이웃끼리
       가깝지 않다). 그래서 readTicks를 못 쓰고 제 고리를 돈다. */
    {
      for (let i = 0; i < n; i += 1) {
        const cnt = head[i].tgt;
        if (!cnt) continue;
        // 표적은 태그(u32)라 float32로는 깨진다 — Float64.
        const out = new Float64Array(cnt * 2);
        let pf = 0;
        for (let k = 0; k < cnt; k += 1) {
          pf += c.varint();
          out[k * 2] = pf / fps;
          out[k * 2 + 1] = c.u32();
        }
        tracks[i].tgt = out;
      }
    }

    const ups: [number, string, number, number][] = [];
    { let pf = 0;
      const cnt = c.u32();
      for (let i = 0; i < cnt; i += 1) {
        pf += c.varint();
        const id = c.u16();
        const level = c.u8();
        const who = c.u8();
        /* 태그는 이름을 모르는 줄에서도 **반드시 읽는다** — 아래 `if (nm)`은 담을지를
           가릴 뿐이고, 안 읽으면 커서가 4바이트씩 밀려 그 뒤가 통째로 어긋난다. */
        const utag = c.u32();
        const nm = bwUpgradeName(id);
        // 2단계·3단계는 이름 뒤에 단계를 붙인다 — 옛 표기와 같은 자리다.
        if (nm) ups.push([pf / fps, level > 1 ? `${nm} ${level}` : nm, who, utag]);
      } }

    const casts: [number, number, number, string, number][] = [];
    { let pf = 0;
      const cnt = c.u32();
      for (let i = 0; i < cnt; i += 1) {
        pf += c.varint();
        const x = c.u16();
        const y = c.u16();
        const tech = c.u8();
        const who = c.u8();
        casts.push([pf / fps, x / 32, y / 32, BW_TECH_NAME[tech] ?? `?${tech}`, who]);
      } }

    const pings: [number, number, number, number][] = [];
    { let pf = 0;
      const cnt = c.u32();
      for (let i = 0; i < cnt; i += 1) {
        pf += c.varint();
        const x = c.u16();
        const y = c.u16();
        pings.push([pf / fps, x / 32, y / 32, c.u8()]);
      } }

    const res = new Map<number, [number, number, number][]>();
    { const prev = new Map<number, [number, number, number]>();
      const cnt = c.u32();
      for (let i = 0; i < cnt; i += 1) {
        const who = c.u8();
        const p = prev.get(who) ?? [0, 0, 0];
        const row: [number, number, number] = [p[0] + c.varint(), p[1] + c.varint(), p[2] + c.varint()];
        prev.set(who, row);
        const arr = res.get(who) ?? [];
        arr.push([row[0] / fps, row[1], row[2]]);
        res.set(who, arr);
      } }

    const orders = new Map<number, [number, number, number, number][]>();
    { let pf = 0;
      const cnt = c.u32();
      for (let i = 0; i < cnt; i += 1) {
        pf += c.varint();
        const tag = c.u32();
        const x = c.u16();
        const y = c.u16();
        const kind = c.u8();
        const arr = orders.get(tag) ?? [];
        arr.push([pf / fps, x / 32, y / 32, kind]);
        orders.set(tag, arr);
      } }

    const apm = new Map<number, [number, number][]>();
    let apmBucketSec = 5;
    { const cnt = c.u32();
      const bucketFrames = c.u16();
      apmBucketSec = bucketFrames / fps;
      let pb = 0;
      for (let i = 0; i < cnt; i += 1) {
        pb += c.varint();
        const who = c.u8();
        const n = c.varint();
        const arr = apm.get(who) ?? [];
        arr.push([(pb * bucketFrames) / fps, n]);
        apm.set(who, arr);
      } }

    const resFields: [number, number, number, number][] = [];
    {
      let pf = 0;
      const cnt = c.u32();
      for (let i = 0; i < cnt; i += 1) {
        pf += c.varint();
        const x = c.u16();
        const y = c.u16();
        resFields.push([pf / fps, x / 32, y / 32, c.u8()]);
      }
    }

    /* 건설 명령(판 9) — [초, 임자, 일꾼 태그, 타일 x, 타일 y, 건물 이름]. 자리는 **발자국 좌상단 타일**이다
       (원작 action_build 의 tile_pos 그대로 — 픽셀도 가운데도 아니다). 종류는 units.dat 번호를 이름으로 푼다. */
    const builds: [number, number, number, number, number, string][] = [];
    {
      let pf = 0;
      const cnt = c.u32();
      for (let i = 0; i < cnt; i += 1) {
        pf += c.varint();
        const who = c.u8();
        const tag = c.u32();
        const tx = c.u16();
        const ty = c.u16();
        const ty9 = c.u16();
        builds.push([pf / fps, who, tag, tx, ty, BW_UNIT_NAME[ty9] ?? `?${ty9}`]);
      }
    }

    /* 선택(판 10) — [초, 임자, 태그들]. 그 명령을 치른 **뒤의 선택 전체**라 화면은 한 줄만 보면 된다
       (ShiftSelect·ShiftDeselect 를 덤퍼가 풀어 준다 — 차이를 쌓는 셈을 화면이 되풀이하지 않게). */
    const sels: [number, number, number[], number][] = [];
    {
      let pf = 0;
      const cnt = c.u32();
      for (let i = 0; i < cnt; i += 1) {
        pf += c.varint();
        const who = c.u8();
        const kind = hasSelKind ? c.u8() : -1;
        const n = c.u8();
        const tags: number[] = [];
        for (let k = 0; k < n; k += 1) tags.push(c.u32());
        sels.push([pf / fps, who, tags, kind]);
      }
    }

    /* 판 11 네 절 — 에너지(태그마다 [초, 값] 계단) · 탑승 · 자원량 · 처치. */
    const energy = new Map<number, Float32Array>();
    const loads: [number, number, number][] = [];
    const amounts: [number, number, number, number][] = [];
    const kills: [number, number, number, number][] = [];
    {
      {
        let pf = 0;
        const cnt = c.u32();
        const tmp = new Map<number, number[]>();
        for (let i = 0; i < cnt; i += 1) {
          pf += c.varint();
          const tag = c.u32();
          const v = c.u16();
          const a = tmp.get(tag);
          if (a) a.push(pf / fps, v); else tmp.set(tag, [pf / fps, v]);
        }
        for (const [tag, a] of tmp) energy.set(tag, Float32Array.from(a));
      }
      {
        let pf = 0;
        const cnt = c.u32();
        for (let i = 0; i < cnt; i += 1) {
          pf += c.varint();
          const pax = c.u32();
          loads.push([pf / fps, pax, c.u32()]);
        }
      }
      {
        let pf = 0;
        const cnt = c.u32();
        for (let i = 0; i < cnt; i += 1) {
          pf += c.varint();
          const x = c.u16();
          const y = c.u16();
          amounts.push([pf / fps, x / 32, y / 32, c.u16()]);
        }
      }
      {
        let pf = 0;
        const cnt = c.u32();
        for (let i = 0; i < cnt; i += 1) {
          pf += c.varint();
          const who = c.u8();
          const ktag = c.u32();
          kills.push([pf / fps, who, ktag, c.u32()]);
        }
      }
    }

    /* 판 13 — 데미지 절: 수 · 통 프레임 · 줄마다 통 차 · 임자 · 네 몫. */
    const dmg: [number, number, number, number, number, number][] = [];
    let dmgBucketSec = 0;
    if (hasDmg) {
      const cnt = c.u32();
      const bf = c.u16();
      dmgBucketSec = bf / fps;
      let pb = 0;
      for (let i = 0; i < cnt; i += 1) {
        pb += c.varint();
        const who = c.u8();
        const du = c.varint();
        const db = c.varint();
        const tu = c.varint();
        const tb = c.varint();
        dmg.push([(pb * bf) / fps, who, du, db, tu, tb]);
      }
    }

    /* 판 14 — 채집 절(맨 뒤): 자원 절과 같은 꼴(사람마다 앞 줄과의 차) · 값은 누적. */
    const gath: [number, number, number, number][] = [];
    if (hasGath) {
      const prev = new Map<number, [number, number, number]>();
      const cnt = c.u32();
      for (let i = 0; i < cnt; i += 1) {
        const who = c.u8();
        const p = prev.get(who) ?? [0, 0, 0];
        const row: [number, number, number] = [p[0] + c.varint(), p[1] + c.varint(), p[2] + c.varint()];
        prev.set(who, row);
        gath.push([row[0] / fps, who, row[1], row[2]]);
      }
    }

    /* 판 16 — 상태 절(줄마다 varint 프레임차 · u32 태그 · u8 갈래 · u32 값) · 사격 절(varint 프레임차 · u32 태그 · u8 공중 · u32 표적). 태그마다 평평한 배열로 묶는다. */
    const stat = new Map<number, Float64Array>();
    const fires = new Map<number, Float64Array>();
    if (has16) {
      const acc9 = new Map<number, number[]>();
      { let pf = 0; const cnt = c.u32();
        for (let i = 0; i < cnt; i += 1) {
          pf += c.varint(); const tag = c.u32(); const kind = c.u8(); const v = c.u32();
          const a9 = acc9.get(tag); if (a9) a9.push(pf / fps, kind, v); else acc9.set(tag, [pf / fps, kind, v]);
        } }
      for (const [tg9, a9] of acc9) stat.set(tg9, Float64Array.from(a9));
      acc9.clear();
      { let pf = 0; const cnt = c.u32();
        for (let i = 0; i < cnt; i += 1) {
          pf += c.varint(); const tag = c.u32(); const air = c.u8(); const tt = c.u32();
          const a9 = acc9.get(tag); if (a9) a9.push(pf / fps, air, tt); else acc9.set(tag, [pf / fps, air, tt]);
        } }
      for (const [tg9, a9] of acc9) fires.set(tg9, Float64Array.from(a9));
    }
    /* 판 17 — 탄 절 · 타일 절(각 u32 바이트 길이 · u32 줄 수 · 몸 · 타일은 머리 u16 폭·높이). */
    const bullets: Bullet17[] = [];
    let tiles: TileTL17 | null = null;
    if (has17) {
      { const len9 = c.u32(); const n9 = c.u32(); const sc = new Cursor(c.take(len9 - 4));
        const live9 = new Map<number, Bullet17>(); let pf = 0;
        for (let i = 0; i < n9; i += 1) {
          const k = sc.u8(); pf += sc.varint(); const id = sc.u32();
          if (k === 1) { const b9 = live9.get(id); if (b9) { b9.t1 = pf / fps; live9.delete(id); } continue; }
          if (k === 2) { const b9 = live9.get(id); if (b9) b9.th = pf / fps; continue; }   // 닿음(위 Bullet17.th)
          const b9: Bullet17 = { id, t0: pf / fps, th: Infinity, t1: Infinity, wpn: sc.u16(), owner: sc.u8(), src: sc.u32(), tgt: sc.u32(), x: sc.u16(), y: sc.u16(), tx: sc.u16(), ty: sc.u16() };
          live9.set(id, b9); bullets.push(b9);
        } }
      { const len9 = c.u32(); const n9 = c.u32(); const w9 = c.u16(); const h9 = c.u16(); const sc = new Cursor(c.take(len9 - 8));
        const ts = new Float64Array(n9); const ix = new Uint32Array(n9); const vs = new Uint32Array(n9); let pf = 0;
        for (let i = 0; i < n9; i += 1) { pf += sc.varint(); ts[i] = pf / fps; ix[i] = sc.u32(); vs[i] = sc.u32(); }
        tiles = new TileTL17(w9, h9, ts, ix, vs); }
    }

    return { version, leftover: c.left,
      tracks, trustUntil: trustFrame < 0 ? null : trustFrame / fps,
      players, ups, casts, pings, res, apm, apmBucketSec, orders, resFields, builds, sels,
      energy, loads, amounts, kills, dmg, dmgBucketSec, gath, stat, fires, has16, fps, bullets, tiles };
  } catch {
    return null;
  }
}
